mapper.select:

where a.deleted = 0

    and a.title like concat('%', #{title}, '%')


    and a.category_id = #{categoryId}


    and a.status = #{status}


    and a.publisher_id = #{publisherId}


    and (a.title like concat('%', #{params.keyword}, '%') or a.summary like concat('%', #{params.keyword}, '%'))

order by a.is_top desc, a.create_time desc

mapper.update:
update tb_announcement
title = #{title}, content = #{content}, summary = #{summary}, category_id = #{categoryId}, status = #{status}, is_top = #{isTop}, expire_time = #{expireTime}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where id = #{id}
